-- Additive schema: existing rows default to v1. Only the new application opts into v2.
alter table public.diagnoses add column question_flow_version text not null default 'v1' check (question_flow_version in ('v1','v2')), add column question_flow_json jsonb not null default '{}';
alter table public.diagnosis_questions add column flow_version text not null default 'v1', add column relationship_types jsonb not null default '[]', add column concern_types jsonb not null default '[]', add column phase text not null default 'common' check(phase in ('common','relationship','concern','ai_followup','paid_followup')), add column condition_json jsonb not null default '{}', add column priority int not null default 50, add column max_uses int not null default 1 check(max_uses between 0 and 1), add column followup_group text;
create table public.diagnosis_selected_questions (
 diagnosis_id uuid not null references public.diagnoses(id) on delete cascade,
 question_key text not null, snapshot jsonb not null,
 phase text not null check(phase in ('common','relationship','concern','ai_followup','paid_followup')),
 question_source text not null check(question_source in ('common','relationship','concern','ai_selected','ai_generated','paid_followup')),
 selected_reason text not null, position int not null, is_active boolean not null default true,
 displayed_at timestamptz, answered_at timestamptz, answer text, selected_at timestamptz not null default now(),
 primary key(diagnosis_id,question_key)
);
alter table public.diagnosis_selected_questions enable row level security;
revoke all on public.diagnosis_selected_questions from public,anon,authenticated;
grant all on public.diagnosis_selected_questions to service_role;
-- History is server-only: reason and unused/internal selection data never reach a public API.
create function public.save_question_plan(p_diagnosis uuid,p_flow jsonb,p_questions jsonb) returns void language plpgsql set search_path='' as $$
declare q jsonb; n int;
begin
 perform 1 from public.diagnoses where id=p_diagnosis and question_flow_version='v2' for update;
 if not found then raise exception 'v2 diagnosis required'; end if;
 for q in select value from jsonb_array_elements(p_questions) loop
  values(p_diagnosis,q->>'question_key',q,q->>'phase',q->>'question_source',q->>'selected_reason',(q->>'position')::int)
  on conflict(diagnosis_id,question_key) do update set snapshot=excluded.snapshot,phase=excluded.phase,question_source=excluded.question_source,selected_reason=excluded.selected_reason,position=excluded.position,is_active=true,displayed_at=null,answered_at=null,answer=null,selected_at=now() where not public.diagnosis_selected_questions.is_active;
  get diagnostics n=row_count;
  if n>0 then insert into public.analytics_events(event_name,metadata) values('dynamic_question_selected',jsonb_build_object('diagnosis_id',p_diagnosis,'question_key',q->>'question_key','phase',q->>'phase','source',q->>'question_source')); end if;
 end loop;
 update public.diagnoses set question_flow_json=p_flow,updated_at=now() where id=p_diagnosis;
 if coalesce((p_flow->>'paid_followup_needed')::boolean,false) then
  update public.paid_reports set status=case when coalesce((p_flow->>'paid_completed')::boolean,false) then 'queued' else 'awaiting_answers' end,updated_at=now() where diagnosis_id=p_diagnosis and status in ('queued','awaiting_answers');
 end if;
end $$;
create function public.save_dynamic_answer(p_diagnosis uuid,p_key text,p_answer text) returns void language plpgsql set search_path='' as $$
declare q public.diagnosis_selected_questions; d public.diagnoses; old_answer text; changed boolean;
begin
 select * into d from public.diagnoses where id=p_diagnosis for update;
 select * into q from public.diagnosis_selected_questions where diagnosis_id=p_diagnosis and question_key=p_key and is_active for update;
 if q.question_key is null or length(trim(p_answer))=0 or length(p_answer)>2000 then raise exception 'invalid question or answer'; end if;
 if d.status='safety' then raise exception 'safety stopped'; end if;
 if q.phase='paid_followup' then
  if not exists(select 1 from public.payments where diagnosis_id=p_diagnosis and status='paid') or coalesce((d.question_flow_json->>'paid_completed')::boolean,false) then raise exception 'paid answer not allowed'; end if;
 else
  if exists(select 1 from public.diagnosis_analyses where diagnosis_id=p_diagnosis) or d.status not in ('answering','followup','failed') then raise exception 'answers frozen'; end if;
 end if;
 select answer_text into old_answer from public.diagnosis_answers where diagnosis_id=p_diagnosis and question_key=p_key;
 if old_answer=p_answer then return; end if;
 changed:=old_answer is not null;
 if changed and q.phase in ('common','relationship','concern') then
  -- Re-select only when the person changes an answer; ordinary reload never changes the plan.
  delete from public.diagnosis_answers a using public.diagnosis_selected_questions s where a.diagnosis_id=p_diagnosis and s.diagnosis_id=a.diagnosis_id and s.question_key=a.question_key and s.is_active and (case when q.phase='common' then s.phase<>'common' else s.phase='ai_followup' end);
  update public.diagnosis_selected_questions set is_active=false where diagnosis_id=p_diagnosis and is_active and (case when q.phase='common' then phase<>'common' else phase='ai_followup' end);
  update public.diagnoses set question_flow_json=case when q.phase='common' then '{}'::jsonb else question_flow_json - 'final_checked' end,classification_json=null,followup_json=null,status='answering' where id=p_diagnosis;
 end if;
 values(p_diagnosis,nullif(q.snapshot->>'id','')::uuid,p_key,q.snapshot->>'question_text',p_answer,q.phase in ('ai_followup','paid_followup'))
 on conflict(diagnosis_id,question_key) do update set answer_text=excluded.answer_text,question_text=excluded.question_text;
 update public.diagnosis_selected_questions set answer=p_answer,answered_at=now() where diagnosis_id=p_diagnosis and question_key=p_key;
end $$;
create function public.view_dynamic_question(p_diagnosis uuid,p_key text) returns void language plpgsql set search_path='' as $$
declare q public.diagnosis_selected_questions;
begin
 update public.diagnosis_selected_questions set displayed_at=now() where diagnosis_id=p_diagnosis and question_key=p_key and is_active and displayed_at is null returning * into q;
 if q.question_key is not null then insert into public.analytics_events(event_name,metadata) values('dynamic_question_viewed',jsonb_build_object('diagnosis_id',p_diagnosis,'question_key',p_key,'phase',q.phase)); end if;
end $$;
revoke all on function public.save_question_plan(uuid,jsonb,jsonb),public.save_dynamic_answer(uuid,text,text),public.view_dynamic_question(uuid,text) from public,anon,authenticated;
grant execute on function public.save_question_plan(uuid,jsonb,jsonb),public.save_dynamic_answer(uuid,text,text),public.view_dynamic_question(uuid,text) to service_role;

-- Old application instances continue to see only their original public question list.
alter policy active_questions on public.diagnosis_questions using(is_active and flow_version='v1');
alter table public.paid_reports drop constraint paid_reports_status_check;
alter table public.paid_reports add constraint paid_reports_status_check check(status in ('queued','generating','ready','failed','revoked','awaiting_answers'));
-- Versioned candidates; legacy rows and text remain unchanged.

-- Defense in depth: no worker, including a stale deployment, can skip v2 paid questions.
create or replace function public.claim_report(p_diagnosis uuid,p_token uuid) returns setof public.paid_reports language sql set search_path='' as $$
 update public.paid_reports r set status='generating',attempts=attempts+1,lease_token=p_token,lease_until=now()+interval '5 minutes',updated_at=now()
 where r.diagnosis_id=p_diagnosis and r.attempts<5 and (r.status in ('queued','failed') or (r.status='generating' and r.lease_until<now())) and exists(select 1 from public.payments p where p.id=r.payment_id and p.status='paid') and exists(select 1 from public.diagnoses d where d.id=p_diagnosis and d.status<>'safety' and (d.question_flow_version='v1' or coalesce((d.question_flow_json->>'paid_completed')::boolean,false))) returning r.*;
$$;
